#include <zephyr/device.h>
#include <zephyr/drivers/retention.h>
#include <zephyr/init.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(retention, CONFIG_RETENTION_LOG_LEVEL);

#ifdef CONFIG_RETENTION_DEVICE_ENABLED

/*
 * The retention subsystem relies on a device specified by the 'zephyr,retention'
 * chosen node in the devicetree. This device must have a compatible driver
 * enabled via Kconfig.
 */
#define RETENTION_DEV_NODE DT_CHOSEN(zephyr_retention)

#if !DT_NODE_HAS_STATUS(RETENTION_DEV_NODE, okay)
#error "Retention device node (zephyr,retention) is not defined or not enabled in the devicetree."
#endif

static const struct device *retention_dev = DEVICE_DT_GET(RETENTION_DEV_NODE);

static int retention_init(void)
{
    if (!device_is_ready(retention_dev)) {
        LOG_ERR("Retention device %s not ready", retention_dev->name);
        return -ENODEV;
    }
    LOG_DBG("Retention device %s ready", retention_dev->name);
    return 0;
}

SYS_INIT(retention_init, APPLICATION, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);

ssize_t retention_read(off_t offset, void *data, size_t len)
{
    if (!device_is_ready(retention_dev)) {
        return -ENODEV;
    }
    return retention_driver_api(retention_dev)->read(retention_dev, offset, data, len);
}

ssize_t retention_write(off_t offset, const void *data, size_t len)
{
    if (!device_is_ready(retention_dev)) {
        return -ENODEV;
    }
    return retention_driver_api(retention_dev)->write(retention_dev, offset, data, len);
}

size_t retention_get_size(void)
{
    if (!device_is_ready(retention_dev)) {
        return 0;
    }
    return retention_driver_api(retention_dev)->get_size(retention_dev);
}

#else /* !CONFIG_RETENTION_DEVICE_ENABLED */

/*
 * Provide dummy implementations if no retention device is enabled via Kconfig.
 * This prevents linker errors if the subsystem is included but no specific
 * retention hardware is configured.
 */
static int retention_init(void)
{
    LOG_DBG("Retention subsystem initialized without a dedicated device.");
    return 0;
}

SYS_INIT(retention_init, APPLICATION, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);

ssize_t retention_read(off_t offset, void *data, size_t len)
{
    ARG_UNUSED(offset);
    ARG_UNUSED(data);
    ARG_UNUSED(len);
    LOG_WRN("Retention device not enabled, read failed.");
    return -ENODEV;
}

ssize_t retention_write(off_t offset, const void *data, size_t len)
{
    ARG_UNUSED(offset);
    ARG_UNUSED(data);
    ARG_UNUSED(len);
    LOG_WRN("Retention device not enabled, write failed.");
    return -ENODEV;
}

size_t retention_get_size(void)
{
    LOG_WRN("Retention device not enabled, size is 0.");
    return 0;
}

#endif /* CONFIG_RETENTION_DEVICE_ENABLED */
